from datetime import datetime, timezone
from decimal import Decimal

from sqlalchemy import (
    Boolean,
    CheckConstraint,
    DateTime,
    ForeignKey,
    Integer,
    Numeric,
    String,
    UniqueConstraint,
    false,
)
from sqlalchemy.orm import Mapped, mapped_column

from app.database import Base


class NotificationEvent(Base):
    """Notification generated by a triggered market alert."""

    __tablename__ = "notification_events"

    __table_args__ = (
        UniqueConstraint(
            "deduplication_key",
            name="uq_notification_events_deduplication_key",
        ),
        CheckConstraint(
            "reference_price > 0 AND observed_price > 0",
            name="ck_notification_events_positive_prices",
        ),
    )

    id: Mapped[int] = mapped_column(
        Integer,
        primary_key=True,
    )

    alert_id: Mapped[int | None] = mapped_column(
        ForeignKey("market_alerts.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
    )

    user_id: Mapped[int] = mapped_column(
        ForeignKey("users.id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )

    ticker: Mapped[str] = mapped_column(
        String(10),
        nullable=False,
    )

    observed_change_percent: Mapped[Decimal] = mapped_column(
        Numeric(10, 4),
        nullable=False,
    )

    observed_price: Mapped[Decimal] = mapped_column(
        Numeric(18, 6),
        nullable=False,
    )

    reference_price: Mapped[Decimal] = mapped_column(
        Numeric(18, 6),
        nullable=False,
    )

    threshold_percent: Mapped[Decimal] = mapped_column(
        Numeric(8, 4),
        nullable=False,
    )

    triggered_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        default=lambda: datetime.now(timezone.utc),
        nullable=False,
    )

    is_read: Mapped[bool] = mapped_column(
        Boolean,
        nullable=False,
        default=False,
        server_default=false(),
    )

    deduplication_key: Mapped[str] = mapped_column(
        String(128),
        nullable=False,
    )
